import hashlib
import hmac
import os
import struct
import time
from typing import Optional, Tuple

SECRET_KEY = os.urandom(32)
MAX_MSG_SIZE = 65536
HEADER_SIZE = 24

def compute_mac(key: bytes, data: bytes) -> bytes:
    return hmac.new(key, data, hashlib.sha256).digest()

def parse_header(raw: bytes) -> Optional[dict]:
    if len(raw) < HEADER_SIZE:
        return None
    version, flags, msg_type, payload_len, seq_num, frag_offset = struct.unpack(
        '!BBHIIq', raw[:HEADER_SIZE]
    )
    if version != 2:
        return None
    return {
        'version': version,
        'flags': flags,
        'msg_type': msg_type,
        'payload_len': payload_len,
        'seq_num': seq_num,
        'frag_offset': frag_offset
    }

def validate_lengths(header: dict, total_len: int) -> bool:
    """Validate payload length against actual data available."""
    payload_len = header['payload_len']
    if payload_len > MAX_MSG_SIZE:
        return False
    if payload_len == 0 and header['msg_type'] != 0x0001:  # heartbeat
        return False
    # For fragmented messages, validate fragment bounds
    if header['flags'] & 0x02:  # FRAGMENT flag
        frag_offset = header['frag_offset']
        if frag_offset < 0:
            return False
        # Fragment data length is total minus header minus MAC
        frag_data_len = total_len - HEADER_SIZE - 32
        if frag_data_len <= 0:
            return False
        # Ensure fragment doesn't exceed total message size
        if frag_offset + frag_data_len > payload_len:
            return False
    return True

def get_effective_length(header: dict, raw_len: int) -> int:
    """Calculate the effective payload length to process.

    For fragmented messages, this is the fragment size.
    For complete messages, this is the actual available data (capped by declared).
    """
    if header['flags'] & 0x02:  # FRAGMENT flag
        # Fragment: actual data in this packet
        return raw_len - HEADER_SIZE - 32  # subtract header and MAC
    else:
        # Complete message: use minimum of declared and available
        available = raw_len - HEADER_SIZE - 32
        return min(header['payload_len'], available)

def verify_and_extract(raw: bytes, key: bytes) -> Optional[Tuple[dict, bytes]]:
    """Verify MAC and extract payload from a message."""
    if len(raw) < HEADER_SIZE + 32:
        return None

    header = parse_header(raw)
    if header is None:
        return None

    if not validate_lengths(header, len(raw)):
        return None

    # MAC covers header + payload (everything except last 32 bytes)
    mac_offset = len(raw) - 32
    received_mac = raw[mac_offset:]
    signed_data = raw[:mac_offset]

    expected_mac = compute_mac(key, signed_data)
    if not hmac.compare_digest(received_mac, expected_mac):
        return None

    # Extract payload using effective length
    eff_len = get_effective_length(header, len(raw))
    if eff_len <= 0:
        return None
    payload = raw[HEADER_SIZE:HEADER_SIZE + eff_len]

    return header, payload

class MessageAssembler:
    def __init__(self):
        self.fragments = {}  # seq_num -> {offset: data}
        self.expected_sizes = {}  # seq_num -> total expected size

    def add_fragment(self, header: dict, payload: bytes) -> Optional[bytes]:
        seq = header['seq_num']
        offset = header['frag_offset']
        total_size = header['payload_len']

        if seq not in self.fragments:
            self.fragments[seq] = {}
            self.expected_sizes[seq] = total_size
        elif self.expected_sizes[seq] != total_size:
            # Inconsistent total size across fragments
            del self.fragments[seq]
            del self.expected_sizes[seq]
            return None

        self.fragments[seq][offset] = payload

        # Check if we have all data
        assembled = self._try_assemble(seq)
        return assembled

    def _try_assemble(self, seq: int) -> Optional[bytes]:
        expected = self.expected_sizes[seq]
        frags = self.fragments[seq]

        # Sort fragments by offset and check coverage
        sorted_offsets = sorted(frags.keys())
        current = 0
        for off in sorted_offsets:
            if off > current:
                return None  # gap
            current = off + len(frags[off])

        if current < expected:
            return None  # incomplete

        # Assemble - use only up to expected size
        result = bytearray(expected)
        for off, data in sorted(frags.items()):
            end = min(off + len(data), expected)
            copy_len = end - off
            if copy_len > 0:
                result[off:end] = data[:copy_len]

        del self.fragments[seq]
        del self.expected_sizes[seq]
        return bytes(result)

def process_message(raw: bytes, key: bytes, assembler: MessageAssembler) -> Optional[bytes]:
    """Process an incoming message. Returns complete payload or None."""
    result = verify_and_extract(raw, key)
    if result is None:
        return None

    header, payload = result

    if header['flags'] & 0x02:  # Fragment
        return assembler.add_fragment(header, payload)
    else:
        return payload

def handle_client_data(data: bytes) -> Optional[bytes]:
    """Entry point for handling raw client data."""
    assembler = MessageAssembler()
    key = SECRET_KEY
    return process_message(data, key, assembler)
